UPDATE diary_record SET
    mood_code=#{request.moodCode},mood_score=#{request.moodScore},activity_content=#{activity},feeling_content=#{feeling},keyword_text=#{request.keywordText},status=#{status},is_favorite=#{favorite},client_update_time=NOW(),server_version=server_version+1
    WHERE id=#{id} AND user_id=#{userId} AND status<>'2' AND server_version=#{request.serverVersion}
